const $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='firstmove.chess.v1', DAY=86400000, START=new Chess().fen();
const fresh=()=>({version:1,records:{},mistakes:{},daily:{},favorites:[],custom:[],prefs:{side:'w',mode:'learn',course:'italian',variation:'mix',depth:0,opponent:'auto'},lastLine:'',academy:emptyAcademy()});
let db=fresh(),storageOK=true;
try{const raw=localStorage.getItem(KEY);if(raw){const p=JSON.parse(raw);if(p.version===1){for(const k of ['records','mistakes','daily'])if(p[k]&&typeof p[k]==='object'&&!Array.isArray(p[k]))db[k]=p[k];for(const k of ['favorites','custom'])if(Array.isArray(p[k]))db[k]=p[k];if(p.prefs)db.prefs={...db.prefs,...p.prefs};db.lastLine=p.lastLine||'';db.academy=sanitizeAcademy(p.academy);}}}catch(e){storageOK=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(db));}catch(e){storageOK=false;}$('storageWarning').hidden=storageOK;}
let courses=[...COURSES];
function parseLine(pgn,name,id){if(typeof pgn!=='string'||pgn.length>50000)throw Error('Слишком длинная запись.');const clean=pgn.replace(/\{[^}]*\}/g,'').replace(/;[^\n]*/g,'');if(/[()]/.test(clean))throw Error('Вставь одну линию без вложенных вариантов в скобках. Каждую ветку можно добавить отдельно с тем же названием дебюта.');const g=new Chess();g.loadPgn(pgn);const h=g.history({verbose:true});if(h.length<2||h.length>80)throw Error('Нужна линия от 2 до 80 полуходов.');if(h[0].before!==START)throw Error('Пока поддерживаются линии из начальной позиции, без стартового FEN.');return {id,name:String(name).slice(0,90),moves:pgn,pgn:g.pgn(),idea:'Твоя сохранённая линия. Приложение проверяет законность ходов, но не их силу.',notes:{},eco:'',history:h.map(m=>({san:m.san,from:m.from,to:m.to,promotion:m.promotion||'',before:m.before,after:m.after,piece:m.piece,color:m.color,captured:m.captured||''})),sans:h.map(m=>m.san)};}
function loadCustom(){courses=[...COURSES];for(const c of db.custom.slice(0,60)){try{if(!c.id?.startsWith('custom-')||typeof c.name!=='string'||!Array.isArray(c.lines))continue;const lines=c.lines.slice(0,100).map((l,i)=>parseLine(l.pgn,l.name,c.id+'-'+i));if(lines.length)courses.push({id:c.id,name:c.name.slice(0,90),style:'custom',level:0,intro:'Твой репертуар: добавляй отдельные ветки под одним названием.',whitePlan:'Повторяй выбранное продолжение за белых. Оценка позиции движком не выполняется.',blackPlan:'Повторяй выбранное продолжение за чёрных. Оценка позиции движком не выполняется.',warning:'Импорт проверяет правила шахмат, а не теоретическую ценность линии.',lines});}catch(e){console.warn('Не удалось загрузить пользовательскую линию',e.message);}}}
loadCustom();
let S=null,epoch=0,timer=null,filter='all',tab='idea',toastTimer=null,modalFocus=null,drag=null,fastTest=false;
const now=()=>Date.now();const today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
const dayStats=()=>db.daily[today()]||(db.daily[today()]={moves:0,good:0,lines:0,studied:0});
const recordKey=(l,side)=>l.id+':'+side;
const record=(l,side)=>db.records[recordKey(l,side)]||{runs:0,clean:0,box:0,due:0,studied:0};
const dateText=t=>new Date(t).toLocaleDateString('ru-RU',{day:'numeric',month:'short'});
const sideName=s=>s==='w'?'белыми':'чёрными';
const levelName=n=>['ТВОЙ РЕПЕРТУАР','БАЗОВЫЙ','СРЕДНИЙ','ПРОДВИНУТЫЙ'][n]||'ТВОЙ РЕПЕРТУАР';
const styleName=s=>({attack:'АТАКУЮЩИЙ',solid:'НАДЁЖНЫЙ',flexible:'ГИБКИЙ',custom:'ПОЛЬЗОВАТЕЛЬСКИЙ'}[s]);
const prefix=(line,h)=>h.length<=line.sans.length&&h.every((m,i)=>m===line.sans[i]);
function cap(l){return S.depth?Math.min(l.sans.length,S.depth*2):l.sans.length;}
function choose(pool,avoid=''){let opts=pool.filter(l=>l.id!==avoid);if(!opts.length)opts=pool;const weights=opts.map(l=>{const r=record(l,S?.side||db.prefs.side);return (!r.runs&&!r.studied?8:1)+((r.due||Infinity)<=now()?4:0)+4/(1+(r.runs||0)+(r.studied||0));});let n=Math.random()*weights.reduce((a,b)=>a+b,0);return opts.find((l,i)=>(n-=weights[i])<=0)||opts[0];}
function begin(id=db.prefs.course,opts={}){if(window.ACADEMY?.active)Academy.leave();clearTimeout(timer);timer=null;epoch++;invalidateAnalysis();closeModal();const c=courses.find(c=>c.id===id)||courses[0];const mode=['learn','train','exam'].includes(opts.mode||db.prefs.mode)?opts.mode||db.prefs.mode:'learn';const side=['w','b'].includes(opts.side||db.prefs.side)?opts.side||db.prefs.side:'w';let variation=opts.variation??(db.prefs.course===c.id?db.prefs.variation:'mix');if(!c.lines.some(l=>l.id===variation))variation='mix';const pool=variation==='mix'?c.lines:[c.lines.find(l=>l.id===variation)];S={course:c,side,mode,variation,manual:(opts.opponent??db.prefs.opponent)==='manual'&&!opts.review,engineStatus:'idle',engineResult:null,engineError:'',depth:[0,5,8].includes(Number(db.prefs.depth))?Number(db.prefs.depth):0,pool,active:null,game:new Chess(),selected:null,flipped:side==='b',hint:0,view:null,busy:false,done:false,free:false,errors:0,hints:0,tested:0,good:0,failed:new Set(),assisted:new Set(),marked:new Set(),feedback:'',feedbackType:'',pending:null,reviewKey:null,epoch};S.active=opts.first?pool[0]:choose(pool,opts.avoid||'');if(S.manual&&S.mode==='exam')S.mode='learn';if(opts.review){const m=opts.review;for(const san of m.historySans)S.game.move(san);S.pool=c.lines.filter(l=>prefix(l,m.historySans));if(!S.pool.length){toast('Эта позиция больше не найдена в репертуаре.');S.pool=c.lines;S.game.reset();}else{S.active=choose(S.pool);S.depth=0;S.variation='mix';S.reviewKey=m.key;S.mode='train';S.side=m.side;S.flipped=m.side==='b';}}db.prefs={...db.prefs,course:c.id,side:S.side,mode:S.mode,variation:S.variation,depth:S.depth,opponent:S.manual?'manual':'auto'};save();tab='idea';$('library').classList.remove('open');populateVariation();render();scheduleOpponent();}
const movesPlayed=()=>S.game.history();
const matches=()=>S.pool.filter(l=>prefix(l,movesPlayed()));
function options(){if(S.manual&&!S.free){const e=engineForPosition();return e?[e.move.san]:manualBookRows().map(r=>r.move.san);}const h=movesPlayed();return [...new Set(matches().filter(l=>h.length<cap(l)).map(l=>l.sans[h.length]))];}
function target(){return S.manual&&!S.free?manualTarget():S.active.history[movesPlayed().length];}
function myTurn(){return !S.busy&&!S.done&&!S.free&&S.view===null&&S.game.turn()===S.side;}
function scheduleOpponent(){if(S.manual&&!S.free){updateManual();return;}if(S.done||S.free)return;if(movesPlayed().length>=cap(S.active)){finish();return;}if(S.game.turn()===S.side){S.busy=false;render();return;}S.busy=true;render();const e=epoch;timer=setTimeout(()=>{if(!S||e!==epoch||S.done||S.free)return;const m=S.game.move(S.active.sans[movesPlayed().length]);S.busy=false;S.selected=null;S.hint=0;S.feedback=S.mode==='exam'?'Соперник ответил '+m.san+'.':m.san+' · '+explain(m,movesPlayed().length);S.feedbackType='';if(movesPlayed().length>=cap(S.active)){finish();return;}render();},fastTest?0:540);}
function positionKey(){return S.course.id+':'+S.side+':'+S.game.fen().split(' ').slice(0,4).join(' ');}
function markDifficult(kind){if(S.mode==='learn'||S.free||S.manual)return;const k=positionKey(),p=movesPlayed().length;if(kind==='error'&&!S.failed.has(p)){S.failed.add(p);S.errors++;}if(kind==='hint'&&!S.assisted.has(p)){S.assisted.add(p);S.hints++;}if(!S.marked.has(k)){S.marked.add(k);const prev=db.mistakes[k];db.mistakes[k]={key:k,courseId:S.course.id,side:S.side,fen:S.game.fen(),historySans:movesPlayed(),expected:options(),count:(prev?.count||0)+1,last:now()};save();}}
function legalMove(from,to,promotion){try{const g=new Chess(S.game.fen());return g.move({from,to,promotion:promotion||'q'});}catch(e){return null;}}
function attempt(from,to,promotion,source='user'){if(S.manual&&!S.free)return manualAttempt(from,to,promotion,source);if(S.view!==null||S.busy||S.done&&!S.free)return false;const m=legalMove(from,to,promotion);if(!m){S.selected=null;S.feedback='Такой ход сейчас невозможен по правилам. Выбери подсвеченное поле.';S.feedbackType='bad';render();return false;}if(S.free){S.game.move({from,to,promotion:promotion||'q'});S.selected=null;S.feedback=terminalText()||'Свободный разбор: обе стороны ходят вручную. Оценка движком не выполняется.';S.feedbackType='';render();return true;}if(S.game.turn()!==S.side)return false;const h=movesPlayed(),next=[...h,m.san],valid=S.pool.filter(l=>prefix(l,next)&&h.length<cap(l));if(!valid.length){const alt=S.course.lines.filter(l=>prefix(l,next));if(alt.length){S.pending={from,to,promotion,ids:alt.map(l=>l.id)};S.feedback='Ход '+m.san+' есть в другой ветке этого дебюта. Сейчас выбрана конкретная линия.';S.feedbackType='warn';}else{markDifficult('error');S.pending=null;S.feedback='Ход '+m.san+' законен, но не входит в изучаемую линию. Это не означает, что он плохой. Попробуй вспомнить ход репертуара.';S.feedbackType='warn';}S.selected=null;render();return false;}if(source!=='user')markDifficult('hint');const ply=h.length,clean=!S.failed.has(ply)&&!S.assisted.has(ply);S.tested++;if(clean)S.good++;if(S.mode!=='learn'){const d=dayStats();d.moves++;if(clean)d.good++;}if(!valid.some(l=>l.id===S.active.id))S.active=choose(valid);S.game.move({from,to,promotion:promotion||'q'});S.selected=null;S.pending=null;S.hint=0;S.feedback=S.mode==='exam'?'Ход принят.':(clean?'Верно. ':'Ход разобран. ')+m.san+' · '+explain(m,ply+1);S.feedbackType='good';save();if(S.reviewKey||movesPlayed().length>=cap(S.active)){finish();return true;}render();scheduleOpponent();return true;}
function terminalText(){if(S.game.isCheckmate())return 'Мат. Разбор завершён.';if(S.game.isStalemate())return 'Пат. Ничья.';if(S.game.isInsufficientMaterial())return 'Недостаточно материала для мата.';if(S.game.isThreefoldRepetition())return 'Троекратное повторение позиции.';if(S.game.isDraw())return 'Ничейная позиция по правилам.';if(S.game.isCheck())return 'Шах: король должен выйти из-под нападения.';return '';}
function finish(){if(S.manual&&!S.free){updateManual();return;}if(S.done)return;clearTimeout(timer);S.busy=false;S.done=true;S.selected=null;S.hint=0;const clean=S.errors===0&&S.hints===0;if(S.reviewKey){if(clean)delete db.mistakes[S.reviewKey];S.feedback='';}else{const key=recordKey(S.active,S.side),r=record(S.active,S.side);if(S.mode==='learn'){r.studied=(r.studied||0)+1;dayStats().studied++;}else if(cap(S.active)<S.active.sans.length){r.shortRuns=(r.shortRuns||0)+1;dayStats().lines++;}else{r.runs=(r.runs||0)+1;r.clean=(r.clean||0)+(clean?1:0);r.box=clean?Math.min((r.box||0)+1,5):0;r.due=now()+(clean?[0,1,3,7,14,30][r.box]*DAY:600000);r.lastAccuracy=Math.round(100*S.good/Math.max(1,S.tested));dayStats().lines++;}r.last=now();db.records[key]=r;db.lastLine=S.active.id;}save();render();}
function hint(){if(!myTurn()||S.mode==='exam'||!target())return;if(S.mode==='learn'){S.selected=target().from;S.feedback='Фигура выбрана. Нажми на золотое поле назначения.';S.feedbackType='';render();return;}markDifficult('hint');S.hint=Math.min(2,S.hint+1);S.selected=null;S.feedback=S.hint===1?'Подсвечена фигура. Ещё одно нажатие покажет поле назначения.':'Направление и ход показаны. Теперь сделай его на доске.';S.feedbackType='';render();}
function showMove(){if(!myTurn()||S.mode==='exam')return;const m=target();if(m)attempt(m.from,m.to,m.promotion,'show');}
function explain(m,ply){const note=S.active.notes?.[ply];if(note)return note;const me=m.color==='w'?'Белые':'Чёрные';if(m.san==='O-O')return 'Короткая рокировка: король уходит из центра, ладья включается в игру.';if(m.san==='O-O-O')return 'Длинная рокировка: король уходит на ферзевый фланг, ладья занимает линию d.';if(m.san.includes('#'))return 'Мат: у короля нет законного ответа на шах.';if(m.san.includes('+'))return 'Шах заставляет соперника сначала решить вопрос безопасности короля.';if(m.captured)return 'Размен меняет структуру и открывает линии. Посмотри, какая фигура или пешка теперь занимает '+m.to+'.';if(m.piece==='n')return 'Конь выходит на '+m.to+' и влияет на центральные поля. Проверь его нападения.';if(m.piece==='b')return 'Слон занимает диагональ с поля '+m.to+'. Оцени, какие поля и фигуры он контролирует.';if(m.piece==='r')return 'Ладья занимает поле '+m.to+'. Ищи работу по открытой или полуоткрытой линии.';if(m.piece==='q')return 'Ферзь подключается с поля '+m.to+'. Проверь, нельзя ли атаковать его с темпом.';if(m.piece==='k')return 'Король перемещается на '+m.to+'. Проверь его безопасность и права на рокировку.';if(['d4','e4','d5','e5'].includes(m.to))return me+' занимают центр пешкой и контролируют соседние центральные поля.';if(['c3','c6','e3','e6','d3','d6'].includes(m.to))return 'Пешечный ход укрепляет расстановку. Посмотри, какую диагональ он открывает или закрывает.';if(['g3','g6','b3','b6'].includes(m.to))return 'Этот ход может подготовить фианкетто слона. Учитывай ослабленные поля рядом с пешкой.';return 'Сравни контроль полей до и после этого хода. План линии: '+S.active.idea;}
const SHAPES={p:'<circle cx="24" cy="13" r="6"/><path d="M20 20h8l-1 9 6 9H15l6-9z"/><path d="M14 38h20l2 5H12z"/>',r:'<path d="M12 10h6v6h4v-6h4v6h4v-6h6v13l-5 5v10H17V28l-5-5z"/><path d="M13 38h22l2 5H11z"/><path class="detail" d="M16 23h16M18 34h12"/>',n:'<path d="M13 39c0-10 5-12 11-17l-7 3-7-4 6-10 9-4-1-4 9 6c8 9 7 19 4 30z"/><path d="M11 39h27l1 4H10z"/><path class="detail" d="M30 14c5 8 4 16-1 21M15 20l5-5"/><circle class="eye" cx="23" cy="13" r="1.4"/>',b:'<path d="M24 7C10 17 15 24 21 27l-1 7-6 5h20l-6-5-1-7C33 24 38 17 24 7z"/><circle cx="24" cy="6" r="2.6"/><path d="M12 39h24l1 4H11z"/><path class="detail" d="M25 12l-6 8M19 28h10M18 34h12"/>',q:'<path d="M12 16l6 6 6-10 6 10 6-6-5 20H17z"/><circle cx="11" cy="13" r="3"/><circle cx="24" cy="9" r="3"/><circle cx="37" cy="13" r="3"/><path d="M15 36h18l4 7H11z"/><path class="detail" d="M17 29h14M16 36h16"/>',k:'<path d="M15 32C13 27 8 21 12 16c4-4 9-1 12 2 3-3 8-6 12-2 4 5-1 11-3 16l-2 6H17z"/><path d="M13 38h22l2 5H11z"/><path d="M22 5h4v4h4v4h-4v8h-4v-8h-4V9h4z"/><path class="detail" d="M16 32h16"/>'};
const PIECE_NAME={p:'пешка',n:'конь',b:'слон',r:'ладья',q:'ферзь',k:'король'};
function pieceSvg(p){const white=p.color==='w';return '<svg viewBox="0 0 48 48" aria-hidden="true" style="fill:'+(white?'#f5f0e5':'#293238')+';stroke:'+(white?'#37413d':'#101a20')+';stroke-width:1.6;stroke-linejoin:round;stroke-linecap:round">'+SHAPES[p.type].replaceAll('class="detail"','fill="none" stroke="'+(white?'#758178':'#7c8f90')+'" stroke-width="1.3"').replaceAll('class="eye"','stroke="none" fill="'+(white?'#364c40':'#c2cdc3')+'"')+'</svg>';}
function displayedGame(){if(S.view===null)return S.game;const g=new Chess();for(const san of movesPlayed().slice(0,S.view))g.move(san);return g;}
function boardCoords(square){const file=square.charCodeAt(0)-97,rank=Number(square[1])-1;return S.flipped?{x:7-file,y:rank}:{x:file,y:7-rank};}
// Only reveal the next book move when study mode or an explicit training hint permits it.
function visualHint(){
  if(!myTurn()||S.mode==='exam')return null;
  const move=target(),level=S.mode==='learn'?2:S.hint;
  return move&&level?{move,level}:null;
}
const PIECE_WITH={p:'Пешкой',n:'Конём',b:'Слоном',r:'Ладьёй',q:'Ферзём',k:'Королём'};
const PROMOTE_TO={q:'ферзя',r:'ладью',b:'слона',n:'коня'};
function moveInstruction(m){
  return PIECE_WITH[m.piece]+' с '+m.from+' на '+m.to+(m.promotion?' · превратить в '+PROMOTE_TO[m.promotion]:'');
}
function moveDetail(m){
  if(m.san.startsWith('O-O-O'))return 'Длинная рокировка: передвинь короля, ладья переместится сама.';
  if(m.san.startsWith('O-O'))return 'Короткая рокировка: передвинь короля, ладья переместится сама.';
  if(m.promotion)return 'Дойди пешкой до последнего ряда и выбери фигуру в появившемся окне.';
  if(m.captured&&m.piece==='p'&&!S.game.get(m.to))return 'Взятие на проходе: пешка соперника уберётся автоматически.';
  if(m.captured)return 'На выделенном поле — фигура соперника. Возьми её своим ходом.';
  if(m.piece==='n')return 'Конь ходит буквой «Г». Стрелка показывает его ход.';
  return 'Зелёная рамка — фигура. Золотая — куда ходить.';
}
function renderBoardInstruction(hint){
  if(S.manual&&!S.free){
    const {title,detail,icon,kind}=manualInstruction(hint),el=$('boardInstruction');
    const html='<span class="instruction-piece" aria-hidden="true">'+icon+'</span><div><strong>'+esc(title)+'</strong><small>'+esc(detail)+'</small></div>';
    el.className='board-instruction '+kind;if(el.innerHTML!==html)el.innerHTML=html;return;
  }
  let title='',detail='',icon='?',kind='neutral';
  if(hint){
    const m=hint.move;icon=pieceSvg({type:m.piece,color:m.color});kind='guided';
    if(hint.level>=2){title=moveInstruction(m);detail=moveDetail(m);}
    else{title=PIECE_NAME[m.piece].charAt(0).toUpperCase()+PIECE_NAME[m.piece].slice(1)+' на '+m.from;detail='Фигура подсвечена. Поле назначения попробуй вспомнить сам.';}
  }else if(S.free){title=S.game.turn()==='w'?'Ход белых':'Ход чёрных';detail='Свободная доска: обе стороны играют вручную.';icon='↔';}
  else if(S.view!==null){title='Просмотр сыгранной позиции';detail='Вернись к текущей позиции, чтобы продолжить.';icon='‹';}
  else if(S.done){title=S.reviewKey?'Позиция разобрана':'Линия пройдена';detail='Выбери повторение или переходи к следующей ветке.';icon='✓';}
  else if(S.busy||S.game.turn()!==S.side){title='Соперник отвечает';detail='После ответа появится твой следующий ход.';icon='…';kind='waiting';}
  else{title='Твой ход — '+(S.side==='w'?'белые':'чёрные');detail=S.mode==='exam'?'Экзамен: вспомни фигуру и поле без подсказки.':'Вспомни продолжение или нажми «Подсказка».';}
  const el=$('boardInstruction');
  const html='<span class="instruction-piece" aria-hidden="true">'+icon+'</span><div><strong>'+esc(title)+'</strong><small>'+esc(detail)+'</small></div>';
  el.className='board-instruction '+kind;
  if(el.innerHTML!==html)el.innerHTML=html;
}
function drawHintArrow(m){
  const a=boardCoords(m.from),b=boardCoords(m.to),sx=a.x*100+50,sy=a.y*100+50,tx=b.x*100+50,ty=b.y*100+50;
  const defs='<defs><marker id="head" markerWidth="3" markerHeight="3" refX="2.6" refY="1.5" orient="auto"><path d="M0 0L3 1.5L0 3z" fill="#dbef86"/></marker></defs>';
  const attrs=' data-hint-arrow="true" data-from="'+m.from+'" data-to="'+m.to+'" fill="none" stroke="#dbef86" stroke-width="13" stroke-linejoin="round" stroke-linecap="round" stroke-opacity=".94" marker-end="url(#head)"';
  if(m.piece==='n'){
    // Use an L-shaped route rather than suggesting a bishop-like diagonal move.
    const vertical=Math.abs(ty-sy)>Math.abs(tx-sx),bend=vertical?[sx,ty]:[tx,sy];
    const start=vertical?[sx,sy+Math.sign(ty-sy)*34]:[sx+Math.sign(tx-sx)*34,sy];
    const end=vertical?[tx-Math.sign(tx-sx)*16,ty]:[tx,ty-Math.sign(ty-sy)*16];
    return defs+'<polyline points="'+[start,bend,end].map(p=>p.join(',')).join(' ')+'"'+attrs+'/>';
  }
  const d=Math.hypot(tx-sx,ty-sy),ux=(tx-sx)/d,uy=(ty-sy)/d;
  return defs+'<line x1="'+(sx+ux*34)+'" y1="'+(sy+uy*34)+'" x2="'+(tx-ux*16)+'" y2="'+(ty-uy*16)+'"'+attrs+'/>';
}
function renderBoard(){
  const g=displayedGame(),last=g.history({verbose:true}).at(-1),legal=S.selected?S.game.moves({square:S.selected,verbose:true}):[];
  const files=S.flipped?'hgfedcba':'abcdefgh',ranks=S.flipped?'12345678':'87654321';
  const hint=visualHint(),tar=hint?.move,full=hint?.level>=2;let html='';
  for(let r=0;r<8;r++)for(let f=0;f<8;f++){
    const sq=files[f]+ranks[r],p=g.get(sq),dark=(sq.charCodeAt(0)-97+Number(sq[1]))%2===1;
    const source=tar?.from===sq,destination=full&&tar.to===sq;
    const classes=['sq',dark?'dark':'',p?'occupied':'',last&&(last.from===sq||last.to===sq)?'last':'',S.selected===sq?'selected':'',legal.some(m=>m.to===sq)?'legal':'',source?'hint-square':'',destination?'hint-destination':'',p?.type==='k'&&p.color===g.turn()&&g.isCheck()?'in-check':''].filter(Boolean).join(' ');
    const label=sq+(p?', '+(p.color==='w'?'белая сторона, ':'чёрная сторона, ')+PIECE_NAME[p.type]:', пустое поле')+(source?'. Ходи этой фигурой':'')+(destination?'. Поле назначения — сюда':'');
    html+='<button class="'+classes+'" data-square="'+sq+'" aria-label="'+label+'" aria-pressed="'+(S.selected===sq)+'">'+(p?pieceSvg(p):'')+(destination?'<span class="target-label" aria-hidden="true">СЮДА</span>':'')+(f===0?'<span class="coord rank">'+ranks[r]+'</span>':'')+(r===7?'<span class="coord file">'+files[f]+'</span>':'')+'</button>';
  }
  $('board').innerHTML=html;$('viewBadge').hidden=S.view===null;
  $('arrowLayer').innerHTML=full?drawHintArrow(tar):'';
  renderBoardInstruction(hint);
}

function populateVariation(){$('variation').innerHTML='<option value="mix">Разные варианты</option>'+S.course.lines.map(l=>'<option value="'+esc(l.id)+'">'+esc(l.name)+'</option>').join('');$('variation').value=S.variation;}
function renderLibrary(){const q=$('search').value.trim().toLocaleLowerCase('ru-RU');const list=courses.filter(c=>(filter==='all'||filter==='favorites'&&db.favorites.includes(c.id)||c.style===filter)&&(c.name+' '+c.lines.map(l=>l.name).join(' ')).toLocaleLowerCase('ru-RU').includes(q));$('libraryMeta').textContent=list.length+' дебютов · за обе стороны';$('courseList').innerHTML=list.map(c=>{const learnt=c.lines.filter(l=>record(l,S.side).box>=2).length;return '<button class="course-item '+(c.id===S.course.id?'selected':'')+'" data-course="'+esc(c.id)+'"><span class="course-symbol">'+(c.style==='attack'?'♞':c.style==='solid'?'♜':'♝')+'</span><span class="course-info"><strong>'+esc(c.name)+'</strong><small><span>'+c.lines.length+' ветки</span><span>·</span><span>'+(['Свои линии','Базовый','Средний','Продвинутый'][c.level])+'</span></small>'+(learnt?'<span class="course-bar"><i style="width:'+Math.round(100*learnt/c.lines.length)+'%"></i></span>':'')+'</span>'+(db.favorites.includes(c.id)?'<span class="favorite-mark">★</span>':'')+'</button>';}).join('')||'<p class="empty">Ничего не найдено. Попробуй другое название или фильтр.</p>';$('mistakeCount').textContent=Object.keys(db.mistakes).length;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));}
function render(){if(!S)return;renderBoard();renderLibrary();$('courseTitle').textContent=S.course.name;$('courseIntro').textContent=S.course.intro;$('courseEyebrow').textContent=styleName(S.course.style)+' ДЕБЮТ · '+levelName(S.course.level);$('favoriteCurrent').textContent=db.favorites.includes(S.course.id)?'★':'☆';$('favoriteCurrent').setAttribute('aria-pressed',db.favorites.includes(S.course.id));document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===S.mode);b.setAttribute('aria-pressed',b.dataset.mode===S.mode);});document.querySelectorAll('[data-side]').forEach(b=>{b.classList.toggle('active',b.dataset.side===S.side);b.setAttribute('aria-pressed',b.dataset.side===S.side);});$('variation').value=S.variation;$('depth').value=String(S.depth);$('opponentDot').className='side-dot'+(S.side==='b'?' white':'');$('yourDot').className='side-dot'+(S.side==='w'?' white':'');$('yourName').textContent=S.free?'Обе стороны — вручную':'Ты играешь '+sideName(S.side);$('opponentName').textContent=S.free?'Свободный разбор':'Соперник · '+(S.side==='w'?'чёрные':'белые');$('opponentMeta').textContent=S.reviewKey?'Повторение трудной позиции':S.free?'Без шахматного движка':S.variation==='mix'?'Разные ответы из репертуара':S.active.name;$('yourMeta').textContent=S.view!==null?'Просмотр пройденной позиции':S.free?'Можно продолжить позицию любыми законными ходами':'Нажми на фигуру и поле или перетащи фигуру';let pill=S.free?(S.game.turn()==='w'?'Ход белых':'Ход чёрных'):S.view!==null?'Просмотр':S.done?'Линия пройдена':S.busy?'Ответ соперника':'Твой ход';$('turnPill').textContent=pill;$('turnPill').className='live-pill'+(S.busy||S.view!==null?' waiting':'');$('hintButton').disabled=!myTurn()||S.mode==='exam';$('showButton').disabled=!myTurn()||S.mode==='exam';$('hintButton').innerHTML=(S.mode==='learn'?'◇ Выбрать фигуру':S.hint===1?'◇ Показать направление':S.hint>=2?'◇ Подсказка показана':'◇ Подсказка')+' <kbd>H</kbd>';$('showButton').textContent=S.mode==='learn'?'Сделать ход за меня →':'Разобрать этот ход →';$('feedback').className='feedback '+S.feedbackType;$('feedback').innerHTML=esc(S.feedback||(!S.done?(S.mode==='learn'?'Ходи фигурой в зелёной рамке на золотое поле. Направление показано стрелкой.':S.mode==='exam'?'Без подсказок. Доступные ходы фигур подсвечиваются, но ход репертуара нужно вспомнить.':'Вспомни продолжение. Подсказки доступны, но такой ход не считается самостоятельным.') :''))+(S.pending?'<button data-action="switch-branch">Перейти в подходящую ветку →</button>':'');$('sessionScore').textContent=S.free?'Свободная доска · без оценки':S.mode==='learn'?'Изучение · без оценки':S.tested?'Самостоятельно '+S.good+'/'+S.tested+' · отклонения '+S.errors+' · подсказки '+S.hints:'Самостоятельно 0 · отклонения '+S.errors+' · подсказки '+S.hints;const ply=movesPlayed().length,max=cap(S.active);$('sessionProgress').textContent=S.free?ply+' полуходов':S.reviewKey?'1 позиция':Math.min(ply,max)+' / '+max+' полуходов';$('progressBar').style.width=(S.reviewKey?S.done?100:0:Math.min(100,100*ply/Math.max(1,max)))+'%';$('branchCount').textContent=S.course.lines.length;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));for(const t of ['idea','moves','branches'])$(t+'Panel').hidden=t!==tab;renderGuide();renderMoves();renderBranches();renderCompletion();renderManualControls();}
function renderGuide(){if(S.manual&&!S.free){renderManualGuide();return;}const tar=target(),ex=S.mode==='exam'&&!S.done;let title='',text='',label='СЛЕДУЮЩИЙ ШАГ';if(S.free){title='Исследуй позицию';text=terminalText()||'Играй за обе стороны, проверяй свои идеи. Ходы здесь не оцениваются и не влияют на прогресс.';label='СВОБОДНЫЙ РАЗБОР';}else if(S.view!==null){title='Просмотр позиции';text='Это уже сыгранная часть линии. Вернись к текущей позиции, чтобы продолжить тренировку.';label='ИСТОРИЯ ХОДОВ';}else if(S.done||!tar){title=S.reviewKey?'Позиция разобрана':S.active.name;text=S.active.idea;label='ЧТО ЗАПОМНИТЬ';}else if(S.busy){title='Ход соперника';text='Продолжение выбирается из веток этого дебюта. Подготовься ответить.';label='НАБЛЮДАЙ';}else if(S.mode==='learn'||S.hint>=2){title=moveInstruction(tar);text=explain(tar,movesPlayed().length+1);}else if(S.hint===1){title=PIECE_NAME[tar.piece].charAt(0).toUpperCase()+PIECE_NAME[tar.piece].slice(1)+' с '+tar.from;text='Фигура подсвечена на доске. Найди её продолжение в изучаемом репертуаре.';label='ПОДСКАЗКА 1 ИЗ 2';}else{title=S.mode==='exam'?'Вспомни продолжение':'Найди ход';text=S.mode==='exam'?'Сыграй ход репертуара за свою сторону. Подсказки и готовые продолжения отключены.':'Сделай ход на доске. В режиме разных вариантов принимаются все продолжения, записанные в этом дебюте.';label=S.mode==='exam'?'ПРОВЕРКА ПАМЯТИ':'ТВОЙ ХОД';}$('coachTitle').textContent=title;$('coachText').textContent=text;$('coachEyebrow').textContent=label;const reveal=myTurn()&&(S.mode==='learn'||S.hint>=2);$('expectedMoves').innerHTML=reveal?options().map(san=>'<button class="expected-chip" data-expected="'+esc(san)+'" title="Сыграть с подсказкой">'+esc(san)+(options().length>1?'<small>ветка</small>':'')+'</button>').join(''):'';$('yourPlan').textContent=S.side==='w'?S.course.whitePlan:S.course.blackPlan;$('opponentPlan').textContent=S.side==='w'?S.course.blackPlan:S.course.whitePlan;$('courseWarning').textContent=S.course.warning;$('yourPlan').parentElement.hidden=ex;$('opponentPlan').parentElement.hidden=ex;$('courseWarning').closest('.caution').hidden=ex;}
function renderMoves(){const h=movesPlayed(),v=S.view??h.length;let html='';for(let i=0;i<h.length;i+=2){html+='<span class="move-number">'+(i/2+1)+'.</span>';for(let j=i;j<i+2;j++)html+=h[j]?'<button data-ply="'+(j+1)+'" class="'+(v===j+1?'current':'')+'">'+esc(h[j])+'</button>':'<span></span>';}$('moveList').innerHTML=html||'<span class="muted small" style="grid-column:1/-1">Ходы ещё не сделаны.</span>';}
function renderBranches(){if(S.mode==='exam'&&!S.done){$('branchDescription').textContent='В экзамене будущие продолжения скрыты. Они станут доступны после завершения линии.';$('branchList').innerHTML='';return;}$('branchDescription').textContent=S.variation==='mix'?'Соперник выбирает одну из этих веток. Твои сохранённые альтернативы тоже принимаются.':'Сейчас тренируется конкретная линия. Здесь можно выбрать другую.';$('branchList').innerHTML=S.course.lines.map(l=>{const r=record(l,S.side);return '<article class="branch-item '+(S.active.id===l.id?'current':'')+'"><h3>'+esc(l.name)+'</h3><p>'+esc(l.idea)+'</p><button data-line="'+esc(l.id)+'">Учить эту ветку →</button><small>'+l.sans.length+' полуходов'+(r.runs?' · '+r.runs+' тренировок':'')+'</small></article>';}).join('');}
function renderCompletion(){if(S.manual&&!S.free){$('completion').hidden=true;return;}$('completion').hidden=!S.done||S.free;if(!S.done||S.free)return;const clean=S.errors===0&&S.hints===0;let title,text;if(S.reviewKey){title=clean?'Позиция закреплена':'Стоит повторить ещё раз';text=clean?'Продолжение найдено самостоятельно. Позиция убрана из списка трудных.':'В этой попытке была помощь или отклонение. Позиция остаётся в повторении.';}else if(S.mode==='learn'){title='Линия разобрана';text=S.active.name+'. Теперь пройди её без подсказок — так станет понятно, что запомнилось.';}else{title=cap(S.active)<S.active.sans.length?'Начало линии пройдено':clean?'Чистое прохождение':'Хорошая практика';text=S.active.name+'. Самостоятельно: '+S.good+' из '+S.tested+' ходов. '+(cap(S.active)<S.active.sans.length?'Пройден сокращённый отрезок; полная линия ещё не засчитана.':clean?'Следующее повторение: '+dateText(record(S.active,S.side).due)+'.':'Трудные позиции сохранены для повторения.');}$('completion').innerHTML='<div class="eyebrow">'+(S.mode==='exam'?'РЕЗУЛЬТАТ ЭКЗАМЕНА':'ШАГ ВПЕРЁД')+'</div><h2>'+esc(title)+'</h2><p>'+esc(text)+'</p><div class="completion-buttons"><button class="primary" data-action="'+(S.reviewKey?'next-mistake':S.mode==='learn'?'train-current':'next')+'">'+(S.reviewKey?'Следующая позиция →':S.mode==='learn'?'Закрепить без подсказок →':'Другой вариант →')+'</button><button class="secondary" data-action="repeat">Повторить линию</button></div><button class="text-btn" data-action="free">Продолжить на свободной доске</button>';}
function toast(text){clearTimeout(toastTimer);$('toast').textContent=text;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,3500);}
function openModal(title,html){modalFocus=document.activeElement;$('modalTitle').textContent=title;$('modalBody').innerHTML=html;$('modal').hidden=false;document.body.style.overflow='hidden';setTimeout(()=>$('modal').querySelector('input,textarea,button')?.focus(),30);}
function closeModal(){if(!$('modal'))return;const was=!$('modal').hidden;$('modal').hidden=true;document.body.style.overflow='';if(was&&modalFocus?.isConnected)modalFocus.focus();}
function help(){openModal('Учить дебюты — по шагам','<p>Выбери дебют, сторону и вариант. Нажми на фигуру, затем на поле — или перетащи её. Доска автоматически разворачивается под выбранный цвет.</p><div class="help-grid"><div><strong>01 · Изучение</strong><p>Фигура и поле назначения подсвечены сразу. Стрелка и подпись показывают, кем ходить и куда. Оценки за память нет.</p></div><div><strong>02 · Тренировка</strong><p>Ход нужно вспомнить. Первая подсказка показывает фигуру, вторая — направление. Помощь учитывается.</p></div><div><strong>03 · Экзамен</strong><p>Без подсказок и готовых веток. Проверяется знание репертуара, а не сила твоей игры.</p></div></div><h3>Уроки: шахматные принципы</h3><p>Вкладка «Уроки»: 28 тем от центра и развития до игры без ферзей, квадрата, оппозиции и базовых окончаний. В каждом уроке есть объяснение, пример, два задания на доске и вопрос. «Проверить пробелы» помогает выбрать темы по 12 вопросам, но не оценивает рейтинг. Прогресс уроков учитывается отдельно и входит в резервную копию JSON.</p><h3>Разные варианты, а не одна заученная цепочка</h3><p>В режиме «Разные варианты» соперник меняет ветки между прохождениями, отдавая больше веса новым и трудным линиям. Любое записанное продолжение за твою сторону принимается. При выборе конкретной ветки приложение предложит перейти на альтернативу, если узнает твой ход.</p><h3>Что считается ошибкой</h3><p>Законный ход вне базы — это отклонение от выбранного репертуара, не шахматная оценка. В автоматической тренировке проверяется репертуар, не объективная сила хода. В режиме ручного соперника вне базы работает локальный Stockfish; любой законный ход принимается без штрафа. Неточные попытки и подсказки в тренировке сохраняют позицию в «Повторить сложное». Два и более чистых прохождения отражаются в индикаторе дебюта. Интервалы повторения после чистых проходов: 1, 3, 7, 14 и 30 дней.</p><h3>Соперник вручную</h3><p>Переключатель «Соперник → Вручную» сохраняет текущую позицию и останавливает автоматические ответы. За соперника делай любые законные ходы. Пока позиция известна выбранному репертуару, подсказка берётся из базы. Вне базы ответ рассчитывает встроенный Stockfish 19 Lite, без сети и сервера. В изучении стрелка видна сразу после расчёта; в тренировке — по подсказке. Это отдельный разбор без оценки знания дебютов; экзамен доступен с автоматическим соперником.</p><p>«Отменить ход» возвращает реальную позицию на один полуход назад. Кнопка «Сыграть … за соперника» использует подсказку только по твоему нажатию. Если её нет, «Подсказать за соперника» сначала считает вариант и не делает ход автоматически. Расчёт ограничен примерно 0,7 секунды поиска, поэтому это не гарантия лучшего хода. После изменения позиции прежний расчёт отменяется. При ошибке движка старые подсказки не показываются.</p><h3>Атака и защита</h3><p>Фильтры показывают учебный характер репертуара: атакующий, надёжный или гибкий. Любой дебют можно учить за белых и чёрных. Название защиты не означает, что за чёрных нужно играть пассивно.</p><h3>Обозначения ходов</h3><div class="notation"><span>K — король</span><span>Q — ферзь</span><span>R — ладья</span><span>B — слон</span><span>N — конь</span><span>x — взятие</span><span>+ — шах</span><span># — мат</span><span>O-O — короткая рокировка</span></div><p>Клавиши: <kbd>H</kbd> — подсказка, <kbd>F</kbd> — повернуть доску, <kbd>R</kbd> — начать заново, <kbd>←</kbd> <kbd>→</kbd> — просмотр сыгранных позиций, <kbd>Esc</kbd> — закрыть окно. Рокировка: перемести короля на два поля.</p><h3>Приватность и сохранение</h3><p>Всё работает в этом HTML-файле без сети и сервера. Прогресс хранится локально в этом браузере; перенос файла, приватный режим или очистка данных могут повлиять на сохранение. Экспортируй резервную копию в «Мой прогресс», чтобы перенести её на другой браузер или компьютер. Файлы PGN и прогресс никуда не отправляются.</p><p class="source-note">Правила и проверка ходов: <a href="https://jhlywa.github.io/chess.js/" target="_blank" rel="noopener">chess.js 1.4.0</a> (BSD-2-Clause). Справочник названий дебютов: <a href="https://github.com/lichess-org/chess-openings" target="_blank" rel="noopener">Lichess chess-openings</a> (CC0). Учебные пояснения подготовлены для этого приложения и не являются движковым анализом. Движок: <a href="https://github.com/nmrugg/stockfish.js" target="_blank" rel="noopener">Stockfish.js 19.0.1 Lite Single</a>, GPL-3.0. Файлы движка, лицензия и исходники находятся в vendor/stockfish. Версия приложения 1.3.</p><details><summary class="muted small">Лицензия библиотеки</summary><pre class="legal-text">'+esc(document.querySelector('.licenses pre').textContent)+'</pre></details><details><summary class="muted small">Stockfish — GPL-3.0</summary><pre class="legal-text">'+esc($('stockfishLicense').textContent)+'</pre></details>');}
function dueItems(){const result=[];for(const c of courses)for(const l of c.lines)for(const side of ['w','b']){const r=record(l,side);if(r.runs&&r.due&&r.due<=now())result.push({c,l,side,r});}return result.sort((a,b)=>a.r.due-b.r.due);}
function showStats(){const all=Object.values(db.daily),moves=all.reduce((s,d)=>s+(d.moves||0),0),good=all.reduce((s,d)=>s+(d.good||0),0),runs=all.reduce((s,d)=>s+(d.lines||0),0),d=dayStats(),due=dueItems();const records=Object.values(db.records),trained=records.filter(r=>r.runs).length;openModal('Мой прогресс','<div class="stats-grid"><div class="stat-tile"><b>'+runs+'</b><span>тренировок завершено</span></div><div class="stat-tile"><b>'+(moves?Math.round(100*good/moves)+'%':'—')+'</b><span>ходов самостоятельно</span></div><div class="stat-tile"><b>'+trained+'</b><span>веток / сторон в работе</span></div></div><p class="small muted">Самостоятельно — ход с первой попытки, без подсказки. Изучение в точность не входит. Белые и чёрные учитываются отдельно.</p><h3>Сегодня</h3><div class="stat-row"><span>Завершено тренировок</span><strong>'+(d.lines||0)+'</strong></div><div class="stat-row"><span>Самостоятельных ходов</span><strong>'+(d.good||0)+' / '+(d.moves||0)+'</strong></div><div class="stat-row"><span>Разобрано линий с подсказками</span><strong>'+(d.studied||0)+'</strong></div><div class="stat-row"><span>Трудных позиций</span><strong>'+Object.keys(db.mistakes).length+'</strong></div><div class="stat-row"><span>Линий пора повторить</span><strong>'+due.length+'</strong></div><div class="modal-actions"><button class="primary" data-action="due">Повторение по расписанию →</button><button class="secondary" data-action="mistakes">Трудные позиции</button></div><h3>Репертуар по цветам</h3>'+courses.filter(c=>c.lines.some(l=>record(l,'w').runs||record(l,'b').runs||record(l,'w').studied||record(l,'b').studied)).map(c=>'<div class="stat-row"><span>'+esc(c.name)+'<small><br>Чистых прохождений</small></span><strong>♙ '+c.lines.reduce((s,l)=>s+(record(l,'w').clean||0),0)+' &nbsp; ♟ '+c.lines.reduce((s,l)=>s+(record(l,'b').clean||0),0)+'</strong></div>').join('')+'<h3>Резервная копия</h3><p>Экспорт сохраняет прогресс, избранное и твои PGN-линии. Импорт объединяет данные с текущими, выбирая более свежие записи.</p><div class="modal-actions"><button class="secondary" data-action="backup">↓ Экспорт JSON</button><button class="secondary" data-action="restore">↑ Импорт JSON</button></div>');}
function showMistakes(){const list=Object.values(db.mistakes).filter(m=>courses.some(c=>c.id===m.courseId)).sort((a,b)=>(b.count||0)-(a.count||0));openModal('Повторить сложное',list.length?'<p>Приложение восстановит позицию прямо перед трудным ходом. Найди продолжение без помощи, чтобы убрать её из списка.</p>'+list.map(m=>'<div class="mistake-item"><div><strong>'+esc(courses.find(c=>c.id===m.courseId).name)+'</strong><small>'+sideName(m.side)+' · перед ходом '+Math.floor(m.historySans.length/2+1)+' · '+m.count+' попыток с помощью</small></div><button class="primary" data-review="'+esc(m.key)+'">Повторить →</button></div>').join(''):'<div class="empty-state"><strong>Трудных позиций пока нет</strong><p>Они появятся, если понадобится подсказка или ты отклонишься от репертуара в тренировке или экзамене.</p></div>');}
function review(key){const m=db.mistakes[key];if(!m)return toast('Эта позиция уже закреплена.');begin(m.courseId,{review:m,side:m.side,mode:'train',variation:'mix'});}
function nextMistake(){const list=Object.values(db.mistakes).sort((a,b)=>a.last-b.last),item=list.find(m=>m.key!==S.reviewKey)||list[0];if(item)review(item.key);else{toast('Все трудные позиции закреплены.');showMistakes();}}
function importDialog(){openModal('Добавить свою линию','<p>Вставь PGN из начальной позиции. Чтобы собрать несколько веток в один дебют, используй одинаковое название дебюта при следующих добавлениях.</p><label class="form-label" for="importCourse">Название дебюта</label><input id="importCourse" maxlength="90" value="Мой репертуар" placeholder="Например, Мой ответ на 1.e4"><label class="form-label" for="importName">Название ветки</label><input id="importName" maxlength="90" placeholder="Например, Основной вариант"><label class="form-label" for="importPgn">Одна линия PGN</label><textarea id="importPgn" spellcheck="false" placeholder="1. e4 e5 2. Nf3 Nc6 3. Bc4 Bc5"></textarea><p class="small">От 2 до 80 полуходов. Вложенные варианты в скобках добавляй отдельными линиями. Стартовая позиция FEN пока не поддерживается.</p><div id="importError" class="import-error" role="alert"></div><div class="modal-actions"><button class="primary" data-action="save-pgn">Добавить и учить →</button><button class="secondary" data-action="load-pgn">Открыть PGN-файл</button></div>');}
function savePgn(){try{const courseName=$('importCourse').value.trim(),name=$('importName').value.trim()||'Вариант '+(db.custom.reduce((a,c)=>a+c.lines.length,0)+1),pgn=$('importPgn').value.trim();if(!courseName)throw Error('Укажи название дебюта.');parseLine(pgn,name,'check');let c=db.custom.find(c=>c.name===courseName);if(!c){if(db.custom.length>=60)throw Error('Достигнут лимит 60 пользовательских дебютов.');c={id:'custom-'+now().toString(36)+'-'+Math.random().toString(36).slice(2,6),name:courseName,lines:[]};db.custom.push(c);}if(c.lines.length>=100)throw Error('В одном дебюте можно хранить до 100 веток.');const test=parseLine(pgn,name,'check');if(c.lines.some(l=>parseLine(l.pgn,l.name,'check').sans.join(' ')===test.sans.join(' ')))throw Error('Такая последовательность уже есть в этом дебюте.');c.lines.push({name,pgn:test.pgn});loadCustom();save();filter='all';$('search').value='';begin(c.id,{mode:'learn',variation:c.id+'-'+(c.lines.length-1)});toast('Линия добавлена. Все ходы проверены.');}catch(e){$('importError').textContent='Не удалось добавить: '+e.message;}}
function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function exportPgn(){
  if(S.mode==='exam'&&!S.done)return toast('Экспорт станет доступен после экзамена.');
  const game=new Chess();game.loadPgn(S.done&&!S.free&&!S.manual?S.active.pgn:S.game.pgn());
  game.setHeader('Event',S.manual?'Первый ход — ручной разбор':'Первый ход');
  const title=S.course.name.replace(/["\\\r\n]/g,'');
  if(S.manual){game.removeHeader('Opening');game.setHeader('Study',title);}else game.setHeader('Opening',title);
  game.setHeader('Result',game.isCheckmate()?(game.turn()==='w'?'0-1':'1-0'):game.isDraw()?'1/2-1/2':'*');
  download('chess-line.pgn',game.pgn(),'application/x-chess-pgn');toast('PGN сохранён.');
}

async function restoreFile(file){if(!file)return;try{if(file.size>3000000)throw Error('Файл больше 3 МБ.');const p=JSON.parse(await file.text());if(p.version!==1||!p.records||!p.mistakes||!p.daily||!Array.isArray(p.custom)||!Array.isArray(p.favorites))throw Error('Это не резервная копия «Первого хода».');const merged=JSON.parse(JSON.stringify(db));for(const c of p.custom){if(typeof c.id!=='string'||!/^custom-[a-z0-9-]+$/.test(c.id)||typeof c.name!=='string'||!Array.isArray(c.lines)||c.lines.length>100)throw Error('Некорректный пользовательский дебют.');const lines=c.lines.map((l,i)=>({name:String(l.name||'Ветка').slice(0,90),pgn:parseLine(l.pgn,l.name,c.id+'-'+i).pgn}));const existing=merged.custom.find(x=>x.id===c.id);if(existing){const n=Math.min(existing.lines.length,lines.length);for(let i=0;i<n;i++)if(parseLine(existing.lines[i].pgn,'','').sans.join(' ')!==parseLine(lines[i].pgn,'','').sans.join(' '))throw Error('Конфликт пользовательских веток: '+c.name);if(lines.length>existing.lines.length)existing.lines=lines;}else merged.custom.push({id:c.id,name:c.name.slice(0,90),lines});}if(merged.custom.length>60)throw Error('Слишком много пользовательских дебютов.');const known=[...COURSES,...merged.custom.map(c=>({...c,lines:c.lines.map((l,i)=>parseLine(l.pgn,l.name,c.id+'-'+i))}))];const validKeys=new Set(known.flatMap(c=>c.lines.flatMap(l=>[l.id+':w',l.id+':b'])));if(Object.keys(p.records).length>20000||Object.keys(p.mistakes).length>5000)throw Error('Слишком много записей.');for(const [k,r]of Object.entries(p.records)){if(!validKeys.has(k)||!r||typeof r!=='object')continue;const nr={};for(const f of ['runs','clean','box','due','studied','last','lastAccuracy','shortRuns']){const v=Number(r[f]||0);if(!Number.isFinite(v)||v<0||v>1e14)throw Error('Некорректная статистика.');nr[f]=v;}nr.box=Math.min(5,Math.floor(nr.box));if(!merged.records[k]||(nr.last||0)>(merged.records[k].last||0))merged.records[k]=nr;}
for(const m of Object.values(p.mistakes)){if(!m||!['w','b'].includes(m.side)||!Array.isArray(m.historySans)||m.historySans.length>80)throw Error('Некорректная позиция повторения.');const c=known.find(c=>c.id===m.courseId);if(!c)continue;const g=new Chess();for(const san of m.historySans)g.move(String(san));if(g.turn()!==m.side)throw Error('Неправильная сторона в позиции повторения.');const next=c.lines.filter(l=>prefix(l,m.historySans)&&l.sans.length>m.historySans.length);if(!next.length)continue;const k=c.id+':'+m.side+':'+g.fen().split(' ').slice(0,4).join(' '),nm={key:k,courseId:c.id,side:m.side,fen:g.fen(),historySans:g.history(),expected:[...new Set(next.map(l=>l.sans[m.historySans.length]))],count:Math.min(10000,Math.max(1,Number(m.count)||1)),last:Math.min(now(),Math.max(0,Number(m.last)||0))};if(!merged.mistakes[k]||nm.last>merged.mistakes[k].last)merged.mistakes[k]=nm;}
for(const [date,d]of Object.entries(p.daily)){if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!d)continue;const nd={};for(const f of ['moves','good','lines','studied']){const v=Number(d[f]||0);if(!Number.isFinite(v)||v<0||v>10000000)throw Error('Некорректная дневная статистика.');nd[f]=v;}if(!merged.daily[date]||nd.moves>merged.daily[date].moves||nd.studied>merged.daily[date].studied)merged.daily[date]=nd;}merged.favorites=[...new Set([...merged.favorites,...p.favorites.filter(id=>known.some(c=>c.id===id))])];merged.academy=mergeAcademy(merged.academy,p.academy);db=merged;loadCustom();save();begin(S.course.id);toast('Резервная копия объединена с текущим прогрессом.');}catch(e){toast('Импорт не выполнен: '+e.message);}finally{$('backupFile').value='';}}
let promotionRequest=null;
function requestMove(from,to){const moves=S.game.moves({square:from,verbose:true}).filter(m=>m.to===to);if(moves.some(m=>m.promotion)){promotionRequest={from,to,epoch};openModal('Превращение пешки','<p>Выбери фигуру для превращения.</p><div class="promotion-picker">'+['q','r','b','n'].map(t=>'<button data-promotion="'+t+'">'+pieceSvg({type:t,color:S.game.turn()})+'<small>'+PIECE_NAME[t]+'</small></button>').join('')+'</div>');}else attempt(from,to);}
function canBoardInput(){if(S.manual&&!S.free)return S.view===null&&!S.done&&!S.game.isGameOver();return S.view===null&&!S.busy&&(!S.done||S.free)&&(!S.free?S.game.turn()===S.side:!S.game.isGameOver());}
function squareClick(sq){if(!canBoardInput())return;const p=S.game.get(sq);if(p?.color===S.game.turn()){S.selected=S.selected===sq?null:sq;renderBoard();return;}if(S.selected)requestMove(S.selected,sq);}
$('board').addEventListener('pointerdown',e=>{if(!canBoardInput()||e.button>0)return;const el=e.target.closest('[data-square]');if(!el)return;e.preventDefault();const sq=el.dataset.square,p=S.game.get(sq),own=p?.color===S.game.turn();drag={sq,from:own?sq:null,previous:S.selected,x:e.clientX,y:e.clientY,moving:false,id:e.pointerId};if(own){S.selected=sq;renderBoard();}try{$('board').setPointerCapture(e.pointerId);}catch{};});
$('board').addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId||!drag.from)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>7)drag.moving=true;if(drag.moving){const ghost=$('dragGhost');ghost.hidden=false;ghost.innerHTML=pieceSvg(S.game.get(drag.from));const size=$('board').clientWidth/8;ghost.style.width=size+'px';ghost.style.height=size+'px';ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px';}});
$('board').addEventListener('pointerup',e=>{if(!drag)return;const d=drag;drag=null;$('dragGhost').hidden=true;try{$('board').releasePointerCapture(e.pointerId);}catch{}const el=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-square]');if(!el||!$('board').contains(el))return;const sq=el.dataset.square;if(d.moving&&d.from&&sq!==d.from){requestMove(d.from,sq);}else if(d.from&&sq===d.from){S.selected=d.previous===sq?null:sq;renderBoard();}else squareClick(sq);});
$('board').addEventListener('pointercancel',()=>{drag=null;$('dragGhost').hidden=true;});
$('board').addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)){const sq=e.target.closest('[data-square]')?.dataset.square;if(sq){e.preventDefault();squareClick(sq);}}});
function viewPosition(ply){if(S.mode==='exam'&&!S.done)return toast('Просмотр прошлых позиций отключён до конца экзамена.');const len=movesPlayed().length;S.view=Math.max(0,Math.min(len,ply));if(S.view===len)S.view=null;S.selected=null;render();}
function repeatCurrent(){if(S.reviewKey&&db.mistakes[S.reviewKey])return review(S.reviewKey);begin(S.course.id,{variation:S.active.id,side:S.side,mode:S.mode});}
const actions={trainer(){closeModal();$('library').classList.remove('open');},stats:showStats,help,library(){$('library').classList.toggle('open');},close:closeModal,import:importDialog,mistakes:showMistakes,'save-pgn':savePgn,'load-pgn'(){$('pgnFile').click();},hint,show:showMove,flip(){S.flipped=!S.flipped;renderBoard();},restart:repeatCurrent,repeat:repeatCurrent,back(){viewPosition((S.view??movesPlayed().length)-1);},forward(){viewPosition((S.view??movesPlayed().length)+1);},live(){S.view=null;render();},favorite(){const id=S.course.id;db.favorites=db.favorites.includes(id)?db.favorites.filter(x=>x!==id):[...db.favorites,id];save();render();},next(){begin(S.course.id,{variation:'mix',avoid:S.active.id,mode:S.mode,side:S.side});},'train-current'(){begin(S.course.id,{variation:S.active.id,mode:'train',side:S.side});},'next-mistake':nextMistake,'switch-branch'(){if(!S.pending)return;const p=S.pending;S.variation='mix';S.pool=S.course.lines;S.active=S.course.lines.find(l=>l.id===p.ids[0]);db.prefs.variation='mix';S.pending=null;attempt(p.from,p.to,p.promotion);},free(){clearTimeout(timer);epoch++;invalidateAnalysis();S.manual=false;S.free=true;S.done=true;S.busy=false;S.view=null;S.selected=null;S.hint=0;S.feedback='Свободный разбор: играешь за обе стороны вручную. Здесь нет соперника-движка.';S.feedbackType='';render();},'export-pgn':exportPgn,backup(){download('first-move-backup-'+today()+'.json',JSON.stringify({...db,exportedAt:new Date().toISOString()},null,2),'application/json');toast('Резервная копия сохранена.');},restore(){$('backupFile').click();},due(){const item=dueItems()[0];if(item)begin(item.c.id,{variation:item.l.id,side:item.side,mode:'train'});else toast('На сегодня нет назначенных повторений. Можно выбрать любой дебют.');}};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.action){e.preventDefault();actions[b.dataset.action]?.();return;}if(b.dataset.course){begin(b.dataset.course,{variation:'mix',first:true});return;}if(b.dataset.filter){filter=b.dataset.filter;renderLibrary();return;}if(b.dataset.mode){begin(S.course.id,{mode:b.dataset.mode,side:S.side,variation:S.variation});return;}if(b.dataset.side){begin(S.course.id,{side:b.dataset.side,mode:S.mode,variation:S.variation});return;}if(b.dataset.tab){tab=b.dataset.tab;render();return;}if(b.dataset.line){begin(S.course.id,{variation:b.dataset.line,mode:S.mode,side:S.side});return;}if(b.dataset.ply){viewPosition(Number(b.dataset.ply));return;}if(b.dataset.review){review(b.dataset.review);return;}if(b.dataset.expected){if(!myTurn()||S.mode==='exam')return;const m=S.game.moves({verbose:true}).find(m=>m.san===b.dataset.expected);if(m)attempt(m.from,m.to,m.promotion,'show');return;}if(b.dataset.promotion&&promotionRequest){const p=promotionRequest;promotionRequest=null;closeModal();if(p.epoch===epoch)attempt(p.from,p.to,b.dataset.promotion);}});
$('modal').querySelector('.modal-backdrop').addEventListener('click',closeModal);
$('search').addEventListener('input',renderLibrary);
$('variation').addEventListener('change',e=>begin(S.course.id,{variation:e.target.value,mode:S.mode,side:S.side}));
$('depth').addEventListener('change',e=>{db.prefs.depth=Number(e.target.value);begin(S.course.id,{variation:S.variation,mode:S.mode,side:S.side});});
$('backupFile').addEventListener('change',e=>restoreFile(e.target.files[0]));
$('pgnFile').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>50000)throw Error('Файл больше 50 КБ.');const t=await f.text();if($('importPgn'))$('importPgn').value=t;}catch(err){if($('importError'))$('importError').textContent=err.message;}e.target.value='';});
document.addEventListener('keydown',e=>{if(window.ACADEMY?.active&&$('modal').hidden)return;if(e.key==='Escape'){closeModal();S.selected=null;drag=null;$('dragGhost').hidden=true;$('library').classList.remove('open');renderBoard();return;}if(!$('modal').hidden){if(e.key==='Tab'){const list=[...$('modal').querySelectorAll('button,input,textarea,select,a[href]')].filter(el=>!el.disabled&&!el.hidden);const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}return;}if(e.ctrlKey||e.metaKey||e.altKey||e.target.closest('input,textarea,select'))return;const map={h:'hint',р:'hint',f:'flip',а:'flip',r:'restart',к:'restart',ArrowLeft:'back',ArrowRight:'forward'};const act=map[e.key]||map[e.key.toLowerCase()];if(act){e.preventDefault();actions[act]();}});
window.addEventListener('storage',e=>{if(e.key===KEY)toast('Прогресс изменён в другой вкладке. Обнови эту страницу перед новой тренировкой.');});
window.TRAINER={Chess,get session(){return S;},get data(){return db;},get courses(){return courses;},begin,attempt,hint,showMove,finish,review,parseLine,restoreFile,save,actions,setFast(v){fastTest=!!v;},snapshot(){return {course:S.course.id,line:S.active.id,side:S.side,mode:S.mode,ply:movesPlayed().length,fen:S.game.fen(),done:S.done,busy:S.busy,errors:S.errors,hints:S.hints,tested:S.tested,good:S.good,options:options(),mistakes:Object.keys(db.mistakes).length};}};
// Startup runs after manual.js is loaded by build.cjs.
